17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.util.StringUtils;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
71	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
72	     * addresses are lower-cased before being stored.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
79	     * named logger keeps them addressable independently of the class's diagnostic logging.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Maximum number of owners a single city may contain. A create that would take the owner's city
85	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
86	     */
87	    private static final int CITY_OWNER_LIMIT = 50;
88	
89	    /**
90	     * Maximum number of owners that may be registered on a single day. A create that would take the
91	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
92	     * have already been created that day - is rejected with a 429.
93	     */
94	    private static final int DAILY_OWNER_LIMIT = 100;
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
117	        Collection<Owner> owners;
118	        if (lastName != null) {
119	            owners = this.clinicService.findOwnerByLastName(lastName);
120	        } else {
121	            owners = this.clinicService.findAllOwners();
122	        }
123	        if (owners.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
132	        Owner owner = this.clinicService.findOwnerById(ownerId);
133	        if (owner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
142	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
143	        validateRequiredFields(ownerFieldsDto);
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
147	        owner.setEmail(normalizeEmail(owner.getEmail()));
148	        if (owner.getRegistrationDate() == null) {
149	            owner.setRegistrationDate(LocalDate.now());
150	        }
151	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
152	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
153	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
154	        }
155	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
156	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
157	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
158	        }
159	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
160	            throw new OwnerCityFullException(owner.getCity());
161	        }
162	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= DAILY_OWNER_LIMIT) {
163	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
164	        }
165	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
166	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
167	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
168	        this.clinicService.saveOwner(owner);
169	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
179	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
180	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
181	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
182	     * after normalization is still rejected.
183	     *
184	     * @param ownerFieldsDto the submitted owner fields
185	     */
186	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
187	        List<String> missingFields = new ArrayList<>();
188	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
189	            missingFields.add("firstName");
190	        }
191	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
192	            missingFields.add("lastName");
193	        }
194	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
195	            missingFields.add("address");
196	        }
197	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
198	            missingFields.add("city");
199	        }
200	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
201	            missingFields.add("telephone");
202	        }
203	        if (!missingFields.isEmpty()) {
204	            throw new MissingOwnerFieldsException(missingFields);
205	        }
206	    }
207	
208	    /**
209	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
210	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
211	     * address; the accepted value is lower-cased before it is stored and returned.
212	     *
213	     * @param email the raw email value submitted by the client, or {@code null}
214	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
215	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
216	     */
217	    private String normalizeEmail(String email) {
218	        if (!StringUtils.hasText(email)) {
219	            return email;
220	        }
221	        if (!EMAIL_PATTERN.matcher(email).matches()) {
222	            throw new InvalidOwnerFieldsException(List.of("email"));
223	        }
224	        return email.toLowerCase();
225	    }
226	
227	    /**
228	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
229	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
230	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
231	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
232	     *
233	     * @param city the owner's city
234	     * @param lastName the owner's last name
235	     * @return the assigned customer code
236	     */
237	    private String buildCustomerCode(String city, String lastName) {
238	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
239	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
240	        int sequence = (int) this.clinicService.findAllOwners().stream()
241	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
242	            .count() + 1;
243	        return String.format("%s-%s-%04d", city3, last3, sequence);
244	    }
245	
246	    /**
247	     * Determines whether an existing owner already shares a household with the supplied last name and
248	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
249	     * considers their last name and address a match.
250	     *
251	     * @param lastName the submitted owner's last name
252	     * @param address the submitted owner's address
253	     * @return {@code true} if another owner already has the same normalized last name and address
254	     */
255	    /**
256	     * Counts how many owners already exist that share the supplied first and last name, compared
257	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
258	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
259	     *
260	     * @param firstName the submitted owner's first name
261	     * @param lastName the submitted owner's last name
262	     * @return the number of existing owners with the same first and last name, ignoring case
263	     */
264	    private int countNamesakes(String firstName, String lastName) {
265	        return (int) this.clinicService.findAllOwners().stream()
266	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
267	                && lastName.equalsIgnoreCase(existing.getLastName()))
268	            .count();
269	    }
270	
271	    private boolean isDuplicateHousehold(String lastName, String address) {
272	        return this.clinicService.findAllOwners().stream()
273	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
274	                lastName, address, existing.getLastName(), existing.getAddress()));
275	    }
276	
277	    /**
278	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
279	     * enforce the per-city capacity limit when a new owner is created.
280	     *
281	     * @param city the submitted owner's city
282	     * @return the number of existing owners in that city, ignoring case
283	     */
284	    private long countOwnersInCity(String city) {
285	        return this.clinicService.findAllOwners().stream()
286	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
287	            .count();
288	    }
289	
290	    /**
291	     * Counts how many owners have already been created on the supplied registration date. Used to
292	     * enforce the per-day capacity limit when a new owner is created.
293	     *
294	     * @param registrationDate the registration date of the owner being created
295	     * @return the number of existing owners already registered on that date
296	     */
297	    /**
298	     * Rolls a registration date forward to a business day. A registration date must fall on a
299	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
300	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
301	     * from the registration date (such as the membership number's year segment) and the daily
302	     * create-limit therefore use the adjusted date.
303	     *
304	     * @param date the effective registration date, whether supplied or defaulted to the server date
305	     * @return the same date when it is a weekday, otherwise the next Monday
306	     */
307	    private LocalDate toBusinessDay(LocalDate date) {
308	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
309	            date = date.plusDays(1);
310	        }
311	        return date;
312	    }
313	
314	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
315	        return this.clinicService.findAllOwners().stream()
316	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
317	            .count();
318	    }
319	
320	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
321	    @Override
322	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
323	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
324	        if (currentOwner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        currentOwner.setAddress(ownerFieldsDto.getAddress());
328	        currentOwner.setCity(ownerFieldsDto.getCity());
329	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
330	        currentOwner.setLastName(ownerFieldsDto.getLastName());
331	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
332	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
333	        this.clinicService.saveOwner(currentOwner);
334	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Transactional
339	    @Override
340	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner == null) {
343	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
344	        }
345	        this.clinicService.deleteOwner(owner);
346	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
347	    }
348	
349	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
350	    @Override
351	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
352	        Owner owner = this.clinicService.findOwnerById(ownerId);
353	        if (owner == null) {
354	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
355	        }
356	        HttpHeaders headers = new HttpHeaders();
357	        Pet pet = petMapper.toPet(petFieldsDto);
358	        owner.setId(ownerId);
359	        pet.setOwner(owner);
360	        pet.getType().setName(null);
361	        this.clinicService.savePet(pet);
362	        PetDto petDto = petMapper.toPetDto(pet);
363	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
364	            .buildAndExpand(pet.getId()).toUri());
365	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
366	    }
367	
368	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
369	    @Override
370	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
371	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
372	        if (currentOwner != null) {
373	            Pet currentPet = this.clinicService.findPetById(petId);
374	            if (currentPet != null) {
375	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
376	                currentPet.setName(petFieldsDto.getName());
377	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
378	                this.clinicService.savePet(currentPet);
379	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
380	            }
381	        }
382	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	    }
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
388	        HttpHeaders headers = new HttpHeaders();
389	        Visit visit = visitMapper.toVisit(visitFieldsDto);
390	        Pet pet = new Pet();
391	        pet.setId(petId);
392	        visit.setPet(pet);
393	        this.clinicService.saveVisit(visit);
394	        VisitDto visitDto = visitMapper.toVisitDto(visit);
395	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
396	            .buildAndExpand(visit.getId()).toUri());
397	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
398	    }
399	
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
404	        Owner owner = this.clinicService.findOwnerById(ownerId);
405	        if (owner != null) {
406	            Pet pet = owner.getPet(petId);
407	            if (pet != null) {
408	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
409	            }
410	        }
411	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
412	    }
413	}
